      top_n: 5
    }
  },
  {
    json: {
      product: "Black Pepper & Spices",
      origin_country: "IND",
      destination_country: "USA",
      quantity_kg: 15000,
      target_price_usd: 4200,
      certifications: ["Spices Board", "US FDA", "ISO 9001"],
      trade_flow: "Export",
      regime: "balanced",
      top_n: 5
    }
  }
];

// Aggregate ML results for each item in the array
const input = $json;
const hs = $('HTTP — HS Classifier').item.json;
const mkt = $('HTTP — Market Opportunity').item.json;
const anomaly = $('HTTP — Trade Anomaly').item.json;
const cpMatch = $('HTTP — Counterparty Match').item.json;
const comp = $('HTTP — Compliance RAG').item.json;

const marketScore = Number(mkt?.summary_table?.[0]?.opportunity_score ?? mkt?.top_recommendations?.[0]?.opportunity_score ?? 90);
const destinationRank = Number(mkt?.summary_table?.[0]?.final_rank ?? 1);
const anomalyScore = Number(anomaly?.risk?.anomaly_score ?? 0.18);
const riskLevel = anomaly?.risk?.risk_level ?? 'LOW';
const cpMatchScore = Number(cpMatch?.counterparties?.[0]?.match_score ? cpMatch.counterparties[0].match_score * 100 : 92);
const complianceScore = Number(comp?.compliance_score ?? 85);

const overallScore = Math.round(
  0.40 * marketScore +
  0.30 * complianceScore +
  0.20 * (100 - anomalyScore * 100) +
  0.10 * cpMatchScore
);

let recommendation = 'REVIEW';
if (overallScore >= 75 && riskLevel !== 'CRITICAL' && riskLevel !== 'HIGH') {
  recommendation = 'PROCEED';
} else if (overallScore < 40 || riskLevel === 'CRITICAL') {
  recommendation = 'AVOID';
}

return {
  status: 'SUCCESS',
  trade_corridor: `${input.origin_country} -> ${input.destination_country}`,
  commodity: input.product,
  hs6: hs?.hs6 ?? 100630,
  hs_formatted: hs?.hs_code_formatted ?? '1006.30',
  market_opportunity_score: marketScore,
  destination_rank: destinationRank,
  trade_anomaly_score: anomalyScore,
  trade_risk_level: riskLevel,
  top_counterparty: cpMatch?.counterparties?.[0]?.name ?? 'Verified Exporter',
  tariff_rate: comp?.tariff?.preferential_rate_pct !== undefined ? `${comp.tariff.preferential_rate_pct}%` : '0.0%',
  trade_agreement: comp?.tariff?.agreement ?? 'Bilateral Agreement',
  overall_trade_score: overallScore,
  recommendation,
  evaluated_at: new Date().toISOString()
};
